import * as THREE from 'three';

/** Axis-aligned solid used for collision and bullet traces. */
export interface Solid {
  min: THREE.Vector3;
  max: THREE.Vector3;
}

/** Result of a world ray cast. */
export interface WorldHit {
  dist: number;
  point: THREE.Vector3;
  normal: THREE.Vector3;
}

/**
 * Ray vs AABB slab test.
 * @param o ray origin
 * @param d normalized ray direction
 * @param min box min
 * @param max box max
 * @param maxDist maximum distance
 * @returns hit distance and axis-normal, or null
 */
export function rayAabb(o: THREE.Vector3, d: THREE.Vector3, min: THREE.Vector3, max: THREE.Vector3, maxDist: number) {
  let tmin = 0;
  let tmax = maxDist;
  let axis = -1;
  let sign = 1;
  for (let i = 0; i < 3; i++) {
    const oi = o.getComponent(i);
    const di = d.getComponent(i);
    const lo = min.getComponent(i);
    const hi = max.getComponent(i);
    if (Math.abs(di) < 1e-8) {
      if (oi < lo || oi > hi) return null;
      continue;
    }
    let t1 = (lo - oi) / di;
    let t2 = (hi - oi) / di;
    let s = -1;
    if (t1 > t2) {
      [t1, t2] = [t2, t1];
      s = 1;
    }
    if (t1 > tmin) {
      tmin = t1;
      axis = i;
      sign = s;
    }
    if (t2 < tmax) tmax = t2;
    if (tmin > tmax) return null;
  }
  if (axis < 0) return null; // origin inside
  const n = new THREE.Vector3();
  n.setComponent(axis, sign);
  return { t: tmin, normal: n };
}

/**
 * The arena: a small MW-style urban map ("Shoot House"-like) built from boxes,
 * with collision, ray casting and spawn points.
 */
export class World {
  solids: Solid[] = [];
  spawns: THREE.Vector3[] = [];
  group = new THREE.Group();
  readonly half = 110;

  /**
   * @param scene scene to add the map to
   */
  constructor(scene: THREE.Scene) {
    scene.add(this.group);
    this.build();
  }

  private mats = {
    ground: new THREE.MeshStandardMaterial({ color: 0x7a7362, roughness: 1 }),
    road: new THREE.MeshStandardMaterial({ color: 0x3d3d3f, roughness: 0.95 }),
    concrete: new THREE.MeshStandardMaterial({ color: 0x9a948a, roughness: 0.95 }),
    brick: new THREE.MeshStandardMaterial({ color: 0x8a5a44, roughness: 0.9 }),
    plaster: new THREE.MeshStandardMaterial({ color: 0xc9bca2, roughness: 0.95 }),
    wood: new THREE.MeshStandardMaterial({ color: 0x7a5a3a, roughness: 0.85 }),
    metal: new THREE.MeshStandardMaterial({ color: 0x4f5a52, roughness: 0.6, metalness: 0.4 }),
    container: [0x8b3a2b, 0x2d5a7a, 0x4e6b3a, 0x9a7a2a].map((c) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.7, metalness: 0.3 })),
    sand: new THREE.MeshStandardMaterial({ color: 0xb59f74, roughness: 1 }),
  };

  /**
   * Adds a solid box (center x/z on ground, y = bottom).
   * @param x center x
   * @param y bottom y
   * @param z center z
   * @param w width (x)
   * @param h height (y)
   * @param d depth (z)
   * @param mat material
   * @param solid whether it collides
   */
  box(x: number, y: number, z: number, w: number, h: number, d: number, mat: THREE.Material, solid = true) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    m.position.set(x, y + h / 2, z);
    m.castShadow = true;
    m.receiveShadow = true;
    this.group.add(m);
    if (solid) this.solids.push({ min: new THREE.Vector3(x - w / 2, y, z - d / 2), max: new THREE.Vector3(x + w / 2, y + h, z + d / 2) });
    return m;
  }

  /** Building shell with door gaps on each side and a roof. */
  private building(x: number, z: number, w: number, d: number, h: number, mat: THREE.Material) {
    const t = 1;
    const door = 6;
    const doorH = 8;
    // walls: split each side around a door
    const side = (cx: number, cz: number, len: number, alongX: boolean) => {
      const seg = (len - door) / 2;
      const off = door / 2 + seg / 2;
      if (alongX) {
        this.box(cx - off, 0, cz, seg, h, t, mat);
        this.box(cx + off, 0, cz, seg, h, t, mat);
        this.box(cx, doorH, cz, door, h - doorH, t, mat);
      } else {
        this.box(cx, 0, cz - off, t, h, seg, mat);
        this.box(cx, 0, cz + off, t, h, seg, mat);
        this.box(cx, doorH, cz, t, h - doorH, door, mat);
      }
    };
    side(x, z - d / 2, w, true);
    side(x, z + d / 2, w, true);
    side(x - w / 2, z, d, false);
    side(x + w / 2, z, d, false);
    this.box(x, h, z, w + 1, 0.8, d + 1, this.mats.concrete);
    // windows: dark strips (visual only)
    const winMat = new THREE.MeshStandardMaterial({ color: 0x1b2026, roughness: 0.2, metalness: 0.6 });
    for (const sx of [-1, 1]) {
      const wm = new THREE.Mesh(new THREE.BoxGeometry(w * 0.25, 2.5, 1.05), winMat);
      wm.position.set(x + sx * w * 0.3, h * 0.72, z - d / 2);
      this.group.add(wm);
      const wm2 = wm.clone();
      wm2.position.z = z + d / 2;
      this.group.add(wm2);
    }
    // interior cover
    this.box(x + w * 0.2, 0, z - d * 0.15, 4, 3.4, 2, this.mats.wood);
  }

  private build() {
    const M = this.mats;
    const H = this.half;
    // ground
    const g = new THREE.Mesh(new THREE.PlaneGeometry(H * 2 + 40, H * 2 + 40), M.ground);
    g.rotation.x = -Math.PI / 2;
    g.receiveShadow = true;
    this.group.add(g);
    // roads
    for (const r of [
      [0, 0, H * 2, 18],
      [0, 0, 18, H * 2],
    ]) {
      const m = new THREE.Mesh(new THREE.PlaneGeometry(r[2], r[3]), M.road);
      m.rotation.x = -Math.PI / 2;
      m.position.set(r[0], 0.02, r[1]);
      m.receiveShadow = true;
      this.group.add(m);
    }
    // perimeter walls
    const wallH = 14;
    this.box(0, 0, -H, H * 2, wallH, 2, M.concrete);
    this.box(0, 0, H, H * 2, wallH, 2, M.concrete);
    this.box(-H, 0, 0, 2, wallH, H * 2, M.concrete);
    this.box(H, 0, 0, 2, wallH, H * 2, M.concrete);

    // buildings in the four quadrants
    this.building(-52, -50, 34, 26, 14, M.brick);
    this.building(55, -52, 28, 30, 16, M.plaster);
    this.building(-55, 54, 30, 30, 15, M.plaster);
    this.building(52, 50, 34, 24, 13, M.brick);

    // center plaza: low walls + fountain block
    this.box(0, 0, 0, 10, 3, 10, M.concrete);
    this.box(0, 3, 0, 4, 6, 4, M.concrete);
    for (const [x, z, w, d] of [
      [-22, -14, 12, 1.5],
      [22, 14, 12, 1.5],
      [-14, 22, 1.5, 12],
      [14, -22, 1.5, 12],
    ]) this.box(x, 0, z, w, 3.4, d, M.sand);

    // shipping containers
    const cont = (x: number, z: number, rotX: boolean, i: number, stack = false) => {
      const [w, d] = rotX ? [20, 8] : [8, 20];
      this.box(x, 0, z, w, 8.5, d, M.container[i % 4]);
      if (stack) this.box(x, 8.5, z, w, 8.5, d, M.container[(i + 1) % 4]);
    };
    cont(-85, -10, false, 0, true);
    cont(-85, 20, false, 1);
    cont(85, 10, false, 2, true);
    cont(85, -22, false, 3);
    cont(-20, -85, true, 1);
    cont(20, 85, true, 2, true);
    cont(28, -88, true, 0);
    cont(-26, 86, true, 3);

    // crates + barriers scattered
    const rand = mulberry32(1337);
    for (let i = 0; i < 46; i++) {
      const x = (rand() * 2 - 1) * (H - 12);
      const z = (rand() * 2 - 1) * (H - 12);
      if (Math.abs(x) < 12 && Math.abs(z) < 12) continue;
      if (this.overlaps(x, z, 4)) continue;
      const big = rand() > 0.6;
      const s = big ? 5 : 3.2;
      this.box(x, 0, z, s, s, s, rand() > 0.5 ? M.wood : M.metal);
      if (big && rand() > 0.5) this.box(x + 0.3, s, z - 0.2, 3.2, 3.2, 3.2, M.wood);
    }
    // jersey barriers along roads
    for (let i = -4; i <= 4; i++) {
      if (i === 0) continue;
      this.box(i * 22, 0, 11, 7, 3, 1.4, M.concrete);
      this.box(-11, 0, i * 22 + 5, 1.4, 3, 7, M.concrete);
    }

    // spawn points around the map edges & inside buildings
    for (let a = 0; a < 16; a++) {
      const ang = (a / 16) * Math.PI * 2;
      const r = 70 + (a % 2) * 20;
      const p = new THREE.Vector3(Math.cos(ang) * r, 0, Math.sin(ang) * r);
      if (!this.overlaps(p.x, p.z, 2.5)) this.spawns.push(p);
    }
    this.spawns.push(new THREE.Vector3(-52, 0, -44), new THREE.Vector3(55, 0, -46), new THREE.Vector3(-55, 0, 60), new THREE.Vector3(52, 0, 54));
  }

  /**
   * Whether a vertical column at (x, z) of given radius overlaps any solid near the ground.
   * @param x world x
   * @param z world z
   * @param r radius
   * @returns overlap flag
   */
  overlaps(x: number, z: number, r: number) {
    return this.solids.some((s) => x + r > s.min.x && x - r < s.max.x && z + r > s.min.z && z - r < s.max.z && s.min.y < 4);
  }

  /**
   * Casts a ray against the world (ground + solids).
   * @param o origin
   * @param d normalized direction
   * @param maxDist maximum distance
   * @returns nearest hit or null
   */
  raycast(o: THREE.Vector3, d: THREE.Vector3, maxDist: number): WorldHit | null {
    let best: WorldHit | null = null;
    let bestT = maxDist;
    if (d.y < -1e-6) {
      const t = -o.y / d.y;
      if (t >= 0 && t < bestT) {
        bestT = t;
        best = { dist: t, point: o.clone().addScaledVector(d, t), normal: new THREE.Vector3(0, 1, 0) };
      }
    }
    for (const s of this.solids) {
      const h = rayAabb(o, d, s.min, s.max, bestT);
      if (h && h.t < bestT) {
        bestT = h.t;
        best = { dist: h.t, point: o.clone().addScaledVector(d, h.t), normal: h.normal };
      }
    }
    return best;
  }

  /**
   * Line-of-sight check between two points.
   * @param a from
   * @param b to
   * @returns true if nothing blocks the segment
   */
  visible(a: THREE.Vector3, b: THREE.Vector3) {
    const d = b.clone().sub(a);
    const len = d.length();
    d.divideScalar(len);
    return !this.raycast(a, d, len - 0.1);
  }

  /**
   * Moves an upright box-shaped body with collision + step-up. Mutates `pos` and `vel`.
   * @param pos feet position
   * @param vel velocity
   * @param dt delta seconds
   * @param r horizontal half-extent
   * @param h height
   * @param stepHeight max step-up height
   * @returns whether the body is grounded
   */
  move(pos: THREE.Vector3, vel: THREE.Vector3, dt: number, r: number, h: number, stepHeight: number): boolean {
    const hit = (p: THREE.Vector3) =>
      this.solids.find((s) => p.x + r > s.min.x && p.x - r < s.max.x && p.z + r > s.min.z && p.z - r < s.max.z && p.y + h > s.min.y && p.y < s.max.y);
    // horizontal, per axis with step-up
    for (const axis of ['x', 'z'] as const) {
      const delta = vel[axis] * dt;
      if (delta === 0) continue;
      pos[axis] += delta;
      const s = hit(pos);
      if (s) {
        const rise = s.max.y - pos.y;
        if (rise > 0 && rise <= stepHeight && vel.y <= 1) {
          const up = pos.clone();
          up.y = s.max.y + 0.01;
          if (!hit(up)) {
            pos.y = up.y;
            continue;
          }
        }
        pos[axis] = delta > 0 ? s.min[axis] - r - 0.001 : s.max[axis] + r + 0.001;
        vel[axis] = 0;
      }
    }
    // vertical
    pos.y += vel.y * dt;
    let grounded = false;
    if (pos.y <= 0) {
      pos.y = 0;
      if (vel.y < 0) vel.y = 0;
      grounded = true;
    }
    const s = hit(pos);
    if (s) {
      if (vel.y <= 0) {
        pos.y = s.max.y;
        vel.y = 0;
        grounded = true;
      } else {
        pos.y = s.min.y - h - 0.001;
        vel.y = 0;
      }
    }
    // ground probe (for standing on things without falling into them)
    if (!grounded && vel.y <= 0) {
      const probe = pos.clone();
      probe.y -= 0.08;
      if (probe.y <= 0 || hit(probe)) grounded = true;
    }
    pos.x = THREE.MathUtils.clamp(pos.x, -this.half + 1 + r, this.half - 1 - r);
    pos.z = THREE.MathUtils.clamp(pos.z, -this.half + 1 + r, this.half - 1 - r);
    return grounded;
  }
}

/**
 * Seeded PRNG.
 * @param a seed
 * @returns random function in [0, 1)
 */
export function mulberry32(a: number) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
